      catalogHeaders: ILLUSTRATION_CATALOG_HEADERS, localizedHeaders: ILLUSTRATION_METADATA_HEADERS,
      localizedFields: LOCALIZED_REGISTRY_FIELDS.images, registryHeaders: localizedRegistryHeaderRule('images'),
