async function loadCollectionExperienceFromFiles(experienceId, fileList, { collectionId = '' } = {}) {
  const files = selectedCollectionFiles(fileList);
  if (!files.size) throw new Error('Choose the data/collections folder.');
  const text = async (url) => {
    const file = files.get(url);
    if (!file) throw new Error('The selected folder is missing ' + url + '.');
    return file.text();
  };
  const objectUrls = new Map();
  const resolveMediaUrl = (url) => {
    const remote = remoteMediaUrl(url);
    if (remote) return remote;
    const file = files.get(url);
    if (!file) throw new Error('The selected folder is missing media file ' + url + '.');
    if (!objectUrls.has(url)) objectUrls.set(url, URL.createObjectURL(file));
    return objectUrls.get(url);
  };
  try {
    const dataset = await loadCollectionExperienceWithReader(experienceId, { text, resolveMediaUrl, collectionId });
    dataset.release = () => {
      objectUrls.forEach((url) => URL.revokeObjectURL(url));
      objectUrls.clear();
    };
    return dataset;
  } catch (error) {
    objectUrls.forEach((url) => URL.revokeObjectURL(url));
    throw error;
  }
}

function relativeDataPath(url) {
  const prefix = 'data/';
  if (!String(url).startsWith(prefix)) throw new Error('Content path is outside data: ' + url + '.');
  return String(url).slice(prefix.length);
}

async function fileHandleAt(rootHandle, url) {
  const parts = relativeDataPath(url).split('/').filter(Boolean);
  const filename = parts.pop();
  let directory = rootHandle;
  for (const part of parts) directory = await directory.getDirectoryHandle(part);
  return directory.getFileHandle(filename);
}

async function readCollectionTextFromDirectory(rootHandle, url) {
  return (await (await fileHandleAt(rootHandle, url)).getFile()).text();
}

